virtual bool IsAuthenticatedRemoteDebuggingSession();

// Opt-in only to the existing selected-document guard. This is not browser
// authentication, trust, target discovery or local-file authority.
virtual bool MayUseAuxDocumentCapabilities() { return false; }

bool IsTrusted() override;
bool MayUseAuxDocumentCapabilities() override {
  return extension_->id() == aux::kAgentExtensionId &&
         profile_->IsRegularProfile() && !profile_->IsOffTheRecord();
}

if (command_params) {
  auto params = command_params->additional_properties.Clone();
  // Preserve even malformed markers: the original strict document guard
  // must refuse them, never reinterpret their removal as an unguarded call.
  if (const auto* capability = params.Find("__auxDocumentCapability")) {
    protocol_request.Set("auxDocumentCapability", capability->Clone());
    params.Remove("__auxDocumentCapability");
  }
  protocol_request.Set("params", std::move(params));
}
